r=Path(__file__).resolve().parent
required=['reset-task-results.json','secondary-voltage-results.json','sensitivity-results.json','nominal-experiment-audit.json','ca1-adequacy-results.json','generalization-results.json','extended-experiment-audit.json','response-dynamics-results.json','context-response-results.json','variant-precision-results.json']
for filename in required:assert (r/filename).exists(),f'Missing final evidence: {filename}'
assert json.loads((r/'extended-experiment-audit.json').read_text())['complete']
primary=json.loads((r/required[0]).read_text());secondary=json.loads((r/required[1]).read_text());sensitivity=json.loads((r/required[2]).read_text());audit=json.loads((r/required[3]).read_text());protocol=primary['protocol'];assert audit['all80trials_complete'] and audit['verified_readout_runs']==240
styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='Body',fontName='Helvetica',fontSize=10,leading=14,spaceAfter=8));styles.add(ParagraphStyle(name='Small',fontName='Helvetica',fontSize=8,leading=11,spaceAfter=6));styles.add(ParagraphStyle(name='TitleCA2',fontName='Helvetica-Bold',fontSize=23,leading=27,textColor=colors.HexColor('#20445b'),spaceAfter=14));styles.add(ParagraphStyle(name='SectionCA2',fontName='Helvetica-Bold',fontSize=15,leading=19,textColor=colors.HexColor('#20445b'),spaceAfter=10));story=[]
def para(text,style='Body'):story.append(Paragraph(text,styles[style]))
def section(title):para(title,'SectionCA2')
def table(headers,rows,widths):
 data=[[Paragraph(html.escape(str(v)),styles['Small']) for v in row] for row in [headers,*rows]];t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e9f0f4')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.8,colors.HexColor('#668091')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f7f9fa')]),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));story.append(t);story.append(Spacer(1,12))
def figure(name,caption):
 p=r/'figures'/name;assert p.exists();from PIL import Image as PILImage
 with PILImage.open(p) as im:w,h=im.size
 story.append(Image(str(p),width=510,height=510*h/w));para(caption,'Small')
def pct(x):return f'{100*x:.1f}%'
def points(x):return f'{100*x:+.1f} points'
para('What CA2 contributes in this modeled circuit','TitleCA2')
para('Controlled input-pattern experiment | CARLsim on the local NVIDIA GPU','Small')
para('We asked whether CA2 pyramidal output makes two equally strong cortical input patterns easier to distinguish in a downstream CA1 sample, and whether competing CA3 input changes that contribution. This is a test of information transmission in a fitted model. It is not a simulation of social recognition, learning, or a particular animal.')
section('Primary result: information in CA1 spikes')
para('Across all five nominal networks, every condition scored 50% with the frozen four-window spike decoder. Cortical input alone produced no CA1 pyramidal spikes; adding CA3 produced five spikes per target in every trial. This gives an uninformative spike-count readout under the tested conditions, not evidence that CA2 lacks a biological function.')
rows=[]
for condition in ['intact','blocked','scrambled']:
 entries=[a for a in primary['per_seed_context_condition'] if a['condition']==condition];rows.append([condition,pct(np.mean([a['heldout_accuracy'] for a in entries])),pct(np.mean([a['rate_only_accuracy'] for a in entries]))])
table(['CA2 pyramidal output','Held-out spike accuracy','Rate-only accuracy'],rows,[165,170,175])
for name,effect in primary['paired_effects'].items():
 interval=effect['descriptive_bootstrap95_interval'];para(f'{name.replace("_"," ").capitalize()}: {points(effect["mean_accuracy_difference"])}; descriptive 95% network bootstrap interval {points(interval[0])} to {points(interval[1])}.')
figure('primary-decoding.png','Predetermined train/test split and nearest-centroid classifier. Reference centroids are learned separately for each network, context and output condition, using only designated training trials. Each point is a model network; chance is 50%. Five networks are not five animals.')
para('This asks how much pattern information the activity makes available to the chosen readout after it is trained for that condition. It does not test an unchanged learned readout during an acute biological lesion. The analysis rule stays fixed; its training centroids differ between conditions.','Small')
para('A null spike result limits this readout and these conditions. It does not show that CA2 has no function in an animal. Silent or saturated target responses, omitted pathways, and the fitted parameters can limit the test.')
para('The zero-width bootstrap interval follows from all five measured spike effects being zero in this assay. It is not a statement that the biological effect is exactly zero, or that every possible spike-timing readout would fail.','Small')
story.append(PageBreak());section('What changed inside CA2?')
para('Across the nominal trials, adding the CA3 input context coincided with a fall in mean CA2 pyramidal response from 2,475 to 244 spikes per trial, about 90%. The responsive pyramidal fraction fell from 13.1% to 1.2%. All four inhibitory populations increased their response rates. This is a clear context-dependent change inside the fitted model even though the chosen CA1 spike-count readout did not distinguish the input classes.')
figure('response-dynamics.png','Bars show mean response rates across five networks; black points are network means. The vertical scale is logarithmic. Rates average spikes over the 200 ms response window and all cells in each modeled population; they are not sustained in-vivo firing rates.')
para('This comparison is descriptive: cortical jitter is drawn separately in the two contexts, rather than held exactly identical. The inhibitory gain was calibrated to CA3 inhibition, so suppression is conditional on that fit and is not an independent discovery of a CA2 function. Core parameter and higher-precision checks in context-response-results.json test whether the pattern depends on those choices.')
para('The direction depends on fitted inhibition: halving the inhibitory multiplier to 50 changes network 31 from suppression to an approximately 26% increase in CA2 pyramidal response with CA3 input. Suppression persists with the tested reversal changes, multiplier 150, and higher precision. This identifies inhibitory strength as a decisive model assumption; it does not establish which regime an animal occupies.')
para('Response-dynamics-results.json also records population and responsive-cell latencies, responsive fractions, repeat similarity, and between-class separation for every modeled population. Silent vectors have undefined similarity and are retained as missing; silent cells are not assigned an artificial spike latency. These secondary descriptions do not replace the primary readout.','Small')
story.append(PageBreak());section('Secondary result: information in voltage responses')
para('The prespecified secondary measure uses mean membrane voltage in four response windows. It can reveal differences below the threshold for generating spikes. It does not replace the primary result and is not called spike transmission or memory.')
figure('secondary-decoding.png','Same input labels, training/test split, and classifier as the primary measure. Baseline-subtracted voltage features use the 128 modeled CA1 pyramidal targets.')
for name,effect in secondary['paired_effects'].items():
 interval=effect['descriptive_bootstrap95_interval'];para(f'{name.replace("_"," ").capitalize()}: {points(effect["mean_difference"])}; descriptive 95% network bootstrap interval {points(interval[0])} to {points(interval[1])}.')
para('Interpret voltage differences only together with the higher-precision and parameter sensitivity results below. Small voltage information can be numerically fragile even when population spike counts change little.')
para('With cortical input alone, voltage classification is 100% in both intact and pyramidal-blocked conditions in every network. The preserved CA2 inhibitory streams can still convey the input pattern. Thus successful voltage classification by itself does not establish a contribution of CA2 pyramidal output. The paired intervention differences, rather than raw accuracy, address that question.')
section('What the controls isolate')
para('Blocking deletes only CA2 pyramidal output. All four CA2 inhibitory streams and the direct CA3 stream stay fixed. Scrambling changes pyramidal cell identities while preserving every spike time, population count, and cell train up to a bijective remapping. This tests whether cell-specific output contributes beyond the amount and timing of activity.')
story.append(PageBreak());section('Why the unchanged export was insufficient')
para('Matching measured ingredients does not guarantee that the assembled circuit reproduces a measured response. After matching single-pulse excitation, the unchanged model produced a CA3 inhibitory voltage difference of about 0.27 mV in magnitude; the published target was 13.8 +/- 2.4 mV. We retained this negative result.')
para('The revised model uses an assumed GABAa reversal of -77.8 mV and a fitted multiplier of 100 on the four inhibitory-to-CA2-pyramidal connections. Other weights retain exported values. This large phenomenological correction is an important limitation, not a measured synaptic conductance. The reversal estimate comes from a recording recipe, not a direct GABAa reversal measurement.')
figure('physiology-report.png','Unused 100 Hz pulse trains check qualitative pathway responses. Traces average the 128 monitored CA2 pyramidal cells, not every CA2 cell. Spike counts cover all modeled cells. Model observations are not animal replicates. All failed earlier checks remain archived.')
para('The reference physiology is Chevaleyre and Siegelbaum (2010), <link href="https://pmc.ncbi.nlm.nih.gov/articles/PMC2905041/" color="#205b80">Strong CA2 pyramidal neuron synapses define a powerful disynaptic cortico-hippocampal loop</link>. Calibration uses aggregate entorhinal layer-II and Schaffer collateral excitation and CA3 inhibition. Layer-III response targets are not silently applied to the modeled MEC layer-II source. Calibration is not independent biological validation.','Small')
section('Downstream biological validation remains limited')
para('A separate CA1 check used the same 1,940-axon single CA3 pulse calibrated against CA2. All 128 modeled CA1 targets fired, both with inhibition intact and with target inhibition removed. This was not an eligible subthreshold EPSP comparison. The model also rested near -69.36 mV, whereas the reference cells were held at -73 mV, so the check is not a matched replication. No source parameter was changed to improve the nominal task result.')
para('Thus numerical reliability does not establish biological validity of the downstream assay. Any null or voltage-based routing result must retain this limitation; strong direct CA3 drive can mask a smaller CA2 contribution.')
section('Model boundaries')
para('The core contains the five exported CA2 types at full counts. Inputs are prescribed MEC layer-II and CA3 events. The downstream assay has 128 CA1 pyramidal cells and selected full-count inhibitory populations. There is no upstream feedback, CA1 pyramidal feedback, explicit dendrite, spatial integration, or long-term learning. This model is not specifically ventral CA1.')
story.append(PageBreak());section('Sensitivity: how dependent is the result?')
figure('sensitivity-effects.png','Paired intact-minus-scrambled accuracy effects, using the same feature definitions, classifier algorithm and train/test split. Centroids are refitted from each variant and condition\'s training responses. Core perturbations and full-core precision use network 31; output-strength and readout-precision checks use all five nominal networks. Perturbation ranges are exploratory, not measured confidence bounds.')
para('The sensitivity analysis changes the assumed inhibitory reversal (-75/-80 mV), the fitted inhibitory multiplier (50/150), and three default-flagged CA2 output connections (half/double effective strength). It also repeats readout calculations at 80 substeps/ms and repeats the complete core task at that precision for network 31.')
para('Reversal variants affect GABAa synapses globally in both CA2 and CA1. Their downstream effects therefore cannot be attributed solely to CA2 inhibition. Gain variants affect only inhibitory-to-CA2-pyramidal connections; output variants affect only the three represented default-flagged CA2 pyramidal output connections.','Small')
variant_precision=json.loads((r/'variant-precision-results.json').read_text());failed=[a for a in variant_precision['results'] if not a['pass']]
para(f'Additional 40/80-substep spot checks cover both contexts in four core variants: {len(variant_precision["results"])-len(failed)} of {len(variant_precision["results"])} meet the pre-existing tolerances. With gain 150 and no CA3 input, intact CA1 basket counts change from 39 to 36 (7.7%, above the 5% tolerance); this case remains numerically unresolved. Two preselected trials per variant cannot establish full classifier convergence. Exact checks are in variant-precision-results.json.')
para('Any effect that changes direction or disappears across these checks is conditional or fragile. A convenient alternative is not selected to replace the frozen nominal result. The full JSON results include both blocked and scrambled comparisons, all per-network values, and the scope of every check.')
para('Every tested variant retains chance-level primary spike classification. Secondary voltage effects depend on assumptions: the intact-minus-blocked effect changes sign in several variants. Doubling the default output strengths produces positive descriptive intervals, but does not validate those assumed strengths. At higher downstream precision the five-network intact-minus-scrambled mean remains +12.5 points; at full-core higher precision the network-31 effect falls from +62.5 to +37.5 points. These results support a conditional voltage signal rather than a robust biological function.')
story.append(PageBreak());section('Does the fixed readout generalize?')
generalization=json.loads((r/'generalization-results.json').read_text())
para('We prospectively added unseen variants of the same two synthetic classes, replacing 10% or 50% of their distinctive cells while preserving total activity. This changes 1% or 5% of the full active ensemble. We also tested CA3 delays of 15 and 35 ms instead of 25 ms. Centroids stayed fixed to the nominal training trials; these new data were never used for training.')
generalization_rows=[]
for group,context in sorted({(a['group'],a['context']) for a in generalization['rows']}):
 entries={c:{k:float(np.mean([a[k] for a in generalization['rows'] if a['group']==group and a['context']==context and a['condition']==c])) for k in ['spikes','voltage']} for c in ['intact','blocked','scrambled']}
 core_count=float(np.mean([a['response_spikes'] for a in generalization['core_response_rows'] if a['group']==group and a['context']==context and a['population']=='CA2_Pyramidal']))
 generalization_rows.append([f'{group}, CA3 {"present" if context else "absent"}',*[f'{pct(entries[c]["spikes"])} / {pct(entries[c]["voltage"])}' for c in ['intact','blocked','scrambled']],f'{core_count:,.1f}'])
table(['Unseen test','Intact','Blocked','Scrambled','CA2 pyramidal spikes'],generalization_rows,[140,95,95,95,85])
para('Each entry gives mean spike / voltage classification accuracy across five networks, with four new trials per case and network. Paired effects and descriptive network bootstrap intervals are recorded in generalization-results.json. Labels follow the majority of the original distinctive pool; the larger change intentionally makes the patterns close to balanced. All tested input patterns must remain distinguishable by the fixed input positive control. These tests do not establish generalization to animal behavior.')
para('All unseen tests retain 50% spike accuracy. For the smaller pattern change without CA3, voltage accuracy is 100% intact, 95% blocked and 55% scrambled. The paired intact-minus-scrambled difference is +45 points (descriptive interval +35 to +50), but intact-minus-blocked is only +5 points (0 to +15): preserved inhibitory streams can still carry class information. The larger pattern change loses this consistent advantage. Both new CA3 delays give 50% voltage accuracy in every condition. Generalization is therefore limited to particular inputs and measures.')
para('The final column gives mean upstream CA2 pyramidal response spikes per trial across all modeled cells. Other core response rates, responsive fractions and latencies are also retained. New trials use fresh jitter, so timing comparisons with nominal trials are descriptive rather than exact matched-jitter counterfactuals. These response measures do not tune or replace the primary decoder.','Small')
section('Uncertainty and scope')
para('Five independently generated networks support descriptive uncertainty about this model. They do not sample animals, input states in natural behavior, or the uncertainty of every exported parameter. The single-network core sensitivity screen does not establish robustness across networks. Balanced label-permutation results are diagnostic and unadjusted for multiple comparisons.')
story.append(PageBreak());section('Exact experiment and evidence')
table(['Item','Frozen nominal configuration'],[['CA2 populations','18,956 pyramidal; 105 basket; 147 wide-arbor basket; 79 bistratified; 94 SP-SR'],['Prescribed input','10,818 MEC source cells; 9,800 active in each pattern; 8,820 shared. CA3 pool 4,096; 1,940 active when present.'],['Timing','Five 100 Hz events with 0-2 ms jitter. Cortical onset 50 ms; CA3 onset 75 ms. Trial 250 ms; response 50-249 ms.'],['State and replication','Fresh process for each trial; network seeds 31-35; 16 trials/network; calibration seed 20 excluded.'],['Readout','128 CA1 targets; 819 basket and 1,962 bistratified cells. Four 50 ms windows; two training and two test repetitions/pattern/context.'],['Numerics','RK4 40 substeps/ms; core checks 20/40, readout checks 40/80; direct checks of inferred effects at higher precision.'],['Synapses','Exported pair-specific short-term plasticity; AMPA/GABAa active; NMDA/GABAb multipliers zero; no long-term learning.'],['Audit',f'{audit["verified_trials"]} core trials and {audit["verified_readout_runs"]} matched replays verified.']], [130,380])
para('The independent audit checks exact input delivery, intact/blocked/bijective-scrambled streams, unchanged inhibitory and CA3 streams, full records for monitored voltage subsets, spikes from all modeled cells, reset baselines, and aggregate connection-count signatures. The latter are not individual-edge hashes; fixed code and seeds support topology matching.','Small')
para('The extended audit additionally verifies 208 core runs and 1,344 matched readouts across parameter changes, higher precision and unseen-input tests. Together with the nominal experiment, this covers 288 core runs and 1,584 readouts. Numerical spot-check failures remain scientific limitations despite successful execution and data-integrity checks.','Small')
para('Files: frozen-task-protocol.json and nominal-parameter-classification.json record configuration and provenance; reset-task-results.json, secondary-voltage-results.json, sensitivity-results.json, and generalization-results.json contain analyses; nominal-experiment-audit.json records verification; methods.txt gives detailed assumptions and reproducibility instructions. Runs and replays contain exact event files, executable/input hashes, configurations, logs, and binary outputs.','Small')
para('The original frozen analysis script is retained. A documented variable-name collision was corrected in analyze_reset_task_v2.py before test-set analysis; the feature and classifier function definitions and inference rules are unchanged. The corrected ingestion was checked on completed real replays.','Small')
para('Backend: CARLsim4 branch feat/meansdSTPPost_hc, source commit 11ea96f750d125e4dcfbf67231429204322fa1bd, with the documented GPU architecture, monitor-capacity and inhibitory-reversal changes. This run uses the archived local implementation and frozen executable, rather than assuming equivalence to another simulator release.','Small')
para('The preserved source archive hash and embedded commit identifier were checked directly. backend-source-provenance.json records modified source/build-file hashes, library hashes, exact build logs and compiler warnings. Local changes also provide CUDA 12 compatibility and timer/check helpers. The archived builds retain CPU thread-wrapper return-type warnings; this study uses GPU mode and does not validate CPU simulation.','Small')
para('REPRODUCE.txt gives the full sequential rerun workflow. prepare_reproduction_copy.py creates a fresh workspace while retaining the exact historical unit-gain reference separately. An isolated copy was checked for all frozen hashes, nominal and unseen input files, CUDA library resolution and analysis/PDF prerequisites. This was a copy and dependency check, not a second full GPU rerun.','Small')
para('Hippocampome source: <link href="https://hippocampome.org/php/simulation_parameters.php" color="#205b80">simulation parameter export</link>. The implemented rows include database defaults; an unflagged row is not proof that each field is directly measured. Effective fitted neuron parameters differ from a matched biological cell model.','Small')
para('The defensible conclusion concerns what this fitted circuit transmits under these controlled conditions, and which assumptions determine that result. Establishing a CA2 function in animals requires matched experimental recordings and biological validation beyond this assay.')
out=r/'output/pdf';out.mkdir(parents=True,exist_ok=True)
