 canvas.saveState();canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#657785'));canvas.drawString(42,25,'CA2-centered CARLsim experiment | Conditional model results');canvas.drawRightString(A4[0]-42,25,str(doc.page));canvas.restoreState()
